parameters.jsonBody:
={
  "messaging_product": "whatsapp",
  "to": "CONFIGURE_YOUR_WHATSAPP_NUMBER",
  "type": "template",
  "template": {
    "name": "lead_reply_alert",
    "language": { "code": "pt_BR" },
    "components": [
      {
        "type": "body",
        "parameters": [
          { "type": "text", "text": "{{ $('Fetch Lead Details').item.json[0].first_name }} {{ $('Fetch Lead Details').item.json[0].last_name }}" },
          { "type": "text", "text": "{{ $('Fetch Lead Details').item.json[0].company_name || 'N/A' }}" },
          { "type": "text", "text": "{{ $('Fetch Lead Details').item.json[0].lead_score }}" },
          { "type": "text", "text": "{{ $json.reply_snippet || 'Sem preview' }}" }
        ]
      }
    ]
  }
}

={
  "blocks": [
    {
      "type": "header",
      "text": { "type": "plain_text", "text": "Lead Respondeu!" }
    },
    {
      "type": "section",
      "fields": [
        { "type": "mrkdwn", "text": "*Nome:*\n{{ $('Fetch Lead Details').item.json[0].first_name }} {{ $('Fetch Lead Details').item.json[0].last_name }}" },
        { "type": "mrkdwn", "text": "*Empresa:*\n{{ $('Fetch Lead Details').item.json[0].company_name || 'N/A' }}" },
        { "type": "mrkdwn", "text": "*Score:*\n{{ $('Fetch Lead Details').item.json[0].lead_score }}" },
        { "type": "mrkdwn", "text": "*Cargo:*\n{{ $('Fetch Lead Details').item.json[0].role || 'N/A' }}" }
      ]
    },
    {
      "type": "section",
      "text": { "type": "mrkdwn", "text": "*Preview:*\n> {{ $json.reply_snippet || 'Sem preview disponivel' }}" }
    },
    {
      "type": "actions",
      "elements": [
        {
          "type": "button",
          "text": { "type": "plain_text", "text": "Ver no CRM" },
          "url": "CONFIGURE_DASHBOARD_URL/outbound/leads?search={{ $('Fetch Lead Details').item.json[0].email }}",
          "style": "primary"
        }
      ]
    }
  ]
}

={
  "lead_id": "{{ $('Reply Webhook').item.json.lead_id }}",
  "type": "alert_sent",
  "channel": "{{ $json.alert_channel || 'slack' }}",
  "subject": "Instant reply alert",
  "metadata": { "alert_type": "reply", "response_time_seconds": {{ Date.now() - new Date($('Reply Webhook').item.json.replied_at).getTime() }} }
}
